      <div class="modal-footer" style="background-color: #f9fafc; border-top: 1px solid #e5e5e5; padding: 12px 20px; display: flex; justify-content: space-between; align-items: center;">
        <button type="button" class="btn btn-default btn-flat btn-close-modal-task" style="border-radius: 3px;">
          <i class="fa fa-times"></i> Batal
        </button>

        <div style="display: flex; gap: 8px;">
