          <button type="button" class="btn btn-default btn-flat" id="btn_back_to_tasks" style="display: none; border-radius: 3px; font-weight: 600;">
            <i class="fa fa-arrow-left"></i> Kembali ke Task
          </button>

          <!-- Step 1 -> Next Button -->
          <button type="button" class="btn btn-primary btn-flat" id="btn_next_to_shipping" style="border-radius: 3px; font-weight: 600; padding: 6px 18px;">
            Next: Pengiriman <i class="fa fa-arrow-right"></i>
          </button>

          <!-- Step 2 -> Final Unified Submit Button -->
          <button type="button" class="btn btn-success btn-flat" id="btn_save_all_assignment" style="display: none; border-radius: 3px; font-weight: 600; padding: 6px 18px;">
            <i class="fa fa-check"></i> Simpan Task & Pengiriman
          </button>
