<!-- Page script -->
<script>
  $(document).ready(function(){
   
    $('.remove-data').click(function(){

      var url = $(this).attr('data-href');

      swal({
          title: "<?= cclang('are_you_sure'); ?>",
          text: "<?= cclang('data_to_be_deleted_can_not_be_restored'); ?>",
          type: "warning",
          showCancelButton: true,
          confirmButtonColor: "#DD6B55",
          confirmButtonText: "<?= cclang('yes_delete_it'); ?>",
          cancelButtonText: "<?= cclang('no_cancel_plx'); ?>",
          closeOnConfirm: true,
          closeOnCancel: true
        },
        function(isConfirm){
          if (isConfirm) {
            document.location.href = url;            
          }
        });

      return false;
    });


    $('#apply').click(function(){

      var bulk = $('#bulk');
      var serialize_bulk = $('#form_campaign_kols').serialize();

      if (bulk.val() == 'delete') {
         swal({
            title: "<?= cclang('are_you_sure'); ?>",
            text: "<?= cclang('data_to_be_deleted_can_not_be_restored'); ?>",
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: "<?= cclang('yes_delete_it'); ?>",
            cancelButtonText: "<?= cclang('no_cancel_plx'); ?>",
            closeOnConfirm: true,
            closeOnCancel: true
          },
          function(isConfirm){
            if (isConfirm) {
               document.location.href = BASE_URL + '/administrator/campaign_kols/delete?' + serialize_bulk;      
            }
          });

        return false;

      } else if(bulk.val() == '')  {
          swal({
            title: "Upss",
            text: "<?= cclang('please_choose_bulk_action_first'); ?>",
            type: "warning",
            showCancelButton: false,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: "Okay!",
            closeOnConfirm: true,
            closeOnCancel: true
          });

        return false;
      }

      return false;

    });/*end appliy click*/


    //check all
    var checkAll = $('#check_all');
    var checkboxes = $('input.check');

    checkAll.on('ifChecked ifUnchecked', function(event) {   
        if (event.type == 'ifChecked') {
            checkboxes.iCheck('check');
        } else {
            checkboxes.iCheck('uncheck');
        }
    });

    checkboxes.on('ifChanged', function(event){
        if(checkboxes.filter(':checked').length == checkboxes.length) {
            checkAll.prop('checked', 'checked');
        } else {
            checkAll.removeProp('checked');
        }
        checkAll.iCheck('update');
    });

    // ========================================================
    // 2-Step Assignment & Shipping Wizard Modal Logic
    // ========================================================
    var csrfName = '<?= $this->security->get_csrf_token_name(); ?>';
    var csrfHash = '<?= $this->security->get_csrf_hash(); ?>';
    var platformsList = <?= json_encode($platforms ?? db_get_all_data('platforms')); ?>;
    var variantsList = <?= json_encode($variants ?? db_get_all_data('variants')); ?>;
    var contentTypeList = <?= json_encode(array_keys(kol_rate_content_types())); ?>;
    var contentTypeAliases = <?= json_encode(kol_content_type_aliases()); ?>;
    window.normalizeContentType = window.normalizeContentType || function (v) {
      var k = String(v === undefined || v === null ? '' : v).toLowerCase().trim();
      return contentTypeAliases[k] || v || '<?= kol_default_content_type(); ?>';
    };
    var productsList = [];
    var currentActiveSelect = null;
    var modalExistingTasks = [];
    var modalExistingShipment = null;
    var modalExistingShipmentItems = [];
    var modalKolData = null;
    var currentStep = 1;
    var modalCampaignStartDate = null;
    var modalCampaignEndDate = null;
    var modalCampaignRemainingBudget = 0;

    function updateSelectStyle($sel) {
      var val = $sel.val();
      var colors = {
        'NEGOTIATION': '#f39c12',
        'ASSIGNED': '#00c0ef',
        'ACTIVE': '#00a65a',
        'COMPLETED': '#3c8dbc',
        'REJECTED': '#dd4b39',
        'CANCELLED': '#777777'
      };
      var color = colors[val] || '#333333';
      $sel.css({
        'border-left': '4px solid ' + color,
        'color': color,
        'background-color': '#fafbfc'
      });
    }

    $('.quick-status-select').each(function() {
      updateSelectStyle($(this));
    });

    // Switch Wizard Steps
    function goToStep(step) {
      currentStep = step;
      if (step === 1) {
        $('#modal_step_1_container').show();
        $('#modal_step_2_container').hide();

        $('#step_indicator_1').css({ 'background': '#ffffff', 'color': '#1f4b6e', 'font-weight': '700' });
        $('#step_indicator_2').css({ 'background': 'rgba(255,255,255,0.16)', 'color': '#ffffff', 'font-weight': '600' });

        $('#btn_next_to_shipping').show();
        $('#btn_back_to_tasks').hide();
        $('#btn_save_all_assignment').hide();
      } else {
        $('#modal_step_1_container').hide();
        $('#modal_step_2_container').fadeIn(200);

        $('#step_indicator_1').css({ 'background': 'rgba(255,255,255,0.16)', 'color': '#ffffff', 'font-weight': '600' });
        $('#step_indicator_2').css({ 'background': '#ffffff', 'color': '#1f4b6e', 'font-weight': '700' });

        $('#btn_next_to_shipping').hide();
        $('#btn_back_to_tasks').show();
        $('#btn_save_all_assignment').show();

        // Populate recipient fields from KOL profile if empty
        if (!$('#shipment_recipient_name').val() && modalKolData) {
          $('#shipment_recipient_name').val(modalKolData.name || '');
          $('#shipment_recipient_phone').val(modalKolData.phone || '');
          var fullAddr = [];
          if (modalKolData.address) fullAddr.push(modalKolData.address);
          if (modalKolData.city) fullAddr.push(modalKolData.city);
          if (modalKolData.province) fullAddr.push(modalKolData.province);
          $('#shipment_shipping_address').val(fullAddr.join(', '));
        }

        // If no items in table, add 1 row
        if ($('#tbody_modal_shipment_items tr').length === 0) {
          addShipmentItemRow();
        }
        recalculateShipmentTotals();
      }
    }

    function renderModalTaskRows() {
      var count = parseInt($('#modal_jumlah_vt').val()) || 0;
      var $tbody = $('#modal_tasks_table_tbody');

      $('#modal_task_count_label').text(count);

      if (count <= 0) {
        $tbody.html('<tr><td colspan="8" class="text-center text-muted" style="padding: 20px;">Masukkan Jumlah Post / VT minimal 1</td></tr>');
        return;
      }

      var currentValues = [];
      $tbody.find('tr.modal-task-row').each(function(idx) {
        currentValues[idx] = {
          id: $(this).find('input[name="tasks['+idx+'][id]"]').val() || '',
          title: $(this).find('input[name="tasks['+idx+'][title]"]').val() || '',
          platform_id: $(this).find('select[name="tasks['+idx+'][platform_id]"]').val() || '',
          variant_id: $(this).find('select[name="tasks['+idx+'][variant_id]"]').val() || '',
          content_type: $(this).find('select[name="tasks['+idx+'][content_type]"]').val() || '',
          estimated_posting_date: $(this).find('input[name="tasks['+idx+'][estimated_posting_date]"]').val() || '',
          budget: $(this).find('input[name="tasks['+idx+'][budget]"]').val() || '',
          notes: $(this).find('textarea[name="tasks['+idx+'][notes]"]').val() || ''
        };
      });

      var html = '';
      for (var i = 0; i < count; i++) {
        var existing = (modalExistingTasks[i]) ? modalExistingTasks[i] : {};
        var curr = (currentValues[i]) ? currentValues[i] : {};

        var id = curr.id !== undefined ? curr.id : (existing.id || '');
        var title = curr.title !== undefined && curr.title !== '' ? curr.title : (existing.title || 'Task #' + (i + 1));
        var platform_id = curr.platform_id !== undefined && curr.platform_id !== '' ? curr.platform_id : (existing.platform_id || '');
        var variant_id = curr.variant_id !== undefined && curr.variant_id !== '' ? curr.variant_id : (existing.variant_id || '');
        var content_type = normalizeContentType(curr.content_type !== undefined && curr.content_type !== '' ? curr.content_type : (existing.content_type || ''));
        var todayStr = new Date().toISOString().split('T')[0];
        var defaultEstDate = modalCampaignStartDate ? modalCampaignStartDate.split(' ')[0] : todayStr;
        var est_date = curr.estimated_posting_date !== undefined && curr.estimated_posting_date !== '' ? curr.estimated_posting_date : (existing.estimated_posting_date || defaultEstDate);
        var rawBudget = curr.budget !== undefined && curr.budget !== '' ? curr.budget : (existing.budget || '0');
        var cleanBudget = parseFloat(rawBudget.toString().replace(/\.00$/, '').replace(/\./g, '')) || 0;
        var budget = (cleanBudget > 0) ? cleanBudget.toLocaleString('id-ID') : '0';
        var notes = curr.notes !== undefined ? curr.notes : (existing.notes || '');

        var platformOptions = '<option value="">- Pilih Platform -</option>';
        if (platformsList && platformsList.length > 0) {
          // If only 1 platform available and not chosen yet, auto-select it
          if (platformsList.length === 1 && !platform_id) {
            platform_id = platformsList[0].id;
          }
          $.each(platformsList, function(pIdx, p) {
            var sel = (platform_id == p.id) ? 'selected' : '';
            var label = p.name;
            if (p.username) {
              label += ' (' + p.username + ')';
            }
            platformOptions += '<option value="' + p.id + '" ' + sel + '>' + label + '</option>';
          });
        } else {
          platformOptions = '<option value="">(KOL belum memiliki platform)</option>';
        }

        var variantOptions = '<option value="">- Pilih -</option>';
        $.each(variantsList, function(vIdx, v) {
          var sel = (variant_id == v.id) ? 'selected' : '';
          variantOptions += '<option value="' + v.id + '" ' + sel + '>' + v.name + '</option>';
        });

        var contentTypeOptions = '';
        var types = contentTypeList;
        $.each(types, function(tIdx, t) {
           var sel = (content_type == t) ? 'selected' : '';
           contentTypeOptions += '<option value="' + t + '" ' + sel + '>' + t + '</option>';
        });

        html += '<tr class="modal-task-row" data-task-index="' + i + '">';
        html += '  <td style="text-align: center; vertical-align: middle; font-weight: bold; color: #3c8dbc;">' + (i + 1) + '</td>';
        html += '  <td style="vertical-align: middle;">';
        html += '    <input type="hidden" name="tasks[' + i + '][id]" value="' + id + '" />';
        html += '    <input type="text" class="form-control input-sm" name="tasks[' + i + '][title]" placeholder="Judul Task" value="' + title + '" required style="border-radius: 3px;" />';
        html += '  </td>';
        html += '  <td style="vertical-align: middle;">';
        html += '    <select class="form-control input-sm" name="tasks[' + i + '][platform_id]" required style="border-radius: 3px;">' + platformOptions + '</select>';
        html += '  </td>';
        html += '  <td style="vertical-align: middle;">';
        html += '    <select class="form-control input-sm" name="tasks[' + i + '][variant_id]" required style="border-radius: 3px;">' + variantOptions + '</select>';
        html += '  </td>';
        html += '  <td style="vertical-align: middle;">';
        html += '    <select class="form-control input-sm" name="tasks[' + i + '][content_type]" required style="border-radius: 3px;">' + contentTypeOptions + '</select>';
        html += '  </td>';
        html += '  <td style="vertical-align: middle;">';
        html += '    <input type="text" class="form-control input-sm modal-task-datepicker" name="tasks[' + i + '][estimated_posting_date]" placeholder="YYYY-MM-DD" value="' + est_date + '" required style="border-radius: 3px;" />';
        html += '  </td>';
        html += '  <td style="vertical-align: middle;">';
        html += '    <input type="text" class="form-control input-sm modal-task-budget-input" name="tasks[' + i + '][budget]" placeholder="0" value="' + budget + '" required style="border-radius: 3px;" />';
        html += '  </td>';
        html += '  <td style="vertical-align: middle;">';
        html += '    <textarea class="form-control input-sm" name="tasks[' + i + '][notes]" rows="1" placeholder="Notes..." style="border-radius: 3px; resize: vertical;">' + notes + '</textarea>';
        html += '  </td>';
        html += '</tr>';
      }

      $tbody.html(html);

      var dpOptions = {
          timepicker: false,
          format: 'Y-m-d',
          formatDate: 'Y-m-d'
      };
      
      if (modalCampaignStartDate) {
          dpOptions.minDate = modalCampaignStartDate.split(' ')[0]; // ensure format is just date
          dpOptions.defaultDate = dpOptions.minDate;
      } else {
          dpOptions.minDate = 0;
      }
      if (modalCampaignEndDate) {
          dpOptions.maxDate = modalCampaignEndDate.split(' ')[0];
      }
      

      $tbody.find('.modal-task-datepicker').datetimepicker(dpOptions);

      $tbody.find('.modal-task-datepicker').inputmask({
          mask: "y-1-2",
          placeholder: "yyyy-mm-dd",
          leapday: "-02-29",
          separator: "-",
          alias: "yyyy/mm/dd"
      });

      // Hard clamp: tanggal ketik manual di luar range campaign langsung dikembalikan ke batas
      $tbody.find('.modal-task-datepicker').off('change.clampRange').on('change.clampRange blur.clampRange', function() {
          var $inp = $(this);
          var v = ($inp.val() || '').trim();
          if (!v || !modalCampaignStartDate) return;
          var minStr = modalCampaignStartDate.split(' ')[0];
          var maxStr = modalCampaignEndDate ? modalCampaignEndDate.split(' ')[0] : null;
          var ok = /^\d{4}-\d{2}-\d{2}$/.test(v) && !isNaN(Date.parse(v));
          var clamped = v;
          if (!ok) {
              clamped = minStr;
          } else {
              if (v < minStr) clamped = minStr;
              if (maxStr && v > maxStr) clamped = maxStr;
          }
          if (clamped !== v) {
              $inp.val(clamped);
              toastr['warning']('Tanggal posting hanya bisa di dalam periode campaign (' + minStr + (maxStr ? ' s/d ' + maxStr : '') + ').');
          }
      });

      distributeDealAmountToTasks();
    }

    function distributeDealAmountToTasks() {
      var rawDeal = $('#modal_deal_amount').val() || '';
      var dealAmt = parseFloat(rawDeal.toString().replace(/\./g, '').replace(/,/g, '.')) || 0;
      var numTasks = parseInt($('#modal_jumlah_vt').val(), 10) || 1;

      if (numTasks > 0 && dealAmt > 0) {
        var perTaskBudget = Math.floor(dealAmt / numTasks);
        var remainder = dealAmt % numTasks;

        $('#modal_tasks_table_tbody tr.modal-task-row').each(function(index) {
          var amount = perTaskBudget;
          if (index === 0) amount += remainder;
          $(this).find('.modal-task-budget-input').val(amount > 0 ? amount.toLocaleString('id-ID') : '');
        });
      }
      recalculateTaskBudgets();
    }

    function recalculateTaskBudgets() {
      var dealAmount = parseFloat($('#modal_deal_amount').val().replace(/\./g, '')) || 0;
      var totalAllocated = 0;

      $('#modal_tasks_table_tbody tr.modal-task-row').each(function() {
        var b = parseFloat($(this).find('.modal-task-budget-input').val().replace(/\./g, '')) || 0;
        totalAllocated += b;
      });

      var remaining = dealAmount - totalAllocated;
      var currentCampaignRemaining = modalCampaignRemainingBudget - dealAmount;

      $('#tracker_deal_amount').text(formatRupiah(dealAmount));
      $('#tracker_allocated_budget').text(formatRupiah(totalAllocated));
      $('#tracker_remaining_budget').text(formatRupiah(remaining));
      $('#tracker_campaign_remaining_budget').text(formatRupiah(currentCampaignRemaining));

      if (dealAmount > modalCampaignRemainingBudget) {
        var message = '<i class="fa fa-warning"></i> Deal amount melebihi sisa budget campaign (' + formatRupiah(modalCampaignRemainingBudget) + ').';
        $('#modal_budget_tracker').css({ 'background': '#fff7ed', 'border-color': '#fed7aa' });
        $('#tracker_campaign_remaining_budget').css('color', '#b54708');
        $('#tracker_warning_msg').html(message).show();
        $('#modal_deal_amount').css('border-color', '#f59e0b');
        return false;
      } else {
        $('#tracker_campaign_remaining_budget').css('color', '#16803c');
        $('#modal_deal_amount').css('border-color', '#00a65a');
      }

      if (dealAmount <= 0 || totalAllocated !== dealAmount) {
        var message = dealAmount <= 0
          ? '<i class="fa fa-warning"></i> Isi nilai deal sebelum lanjut.'
          : totalAllocated > dealAmount
            ? '<i class="fa fa-warning"></i> Alokasi task melebihi nilai deal.'
            : '<i class="fa fa-warning"></i> Alokasi task masih kurang ' + formatRupiah(dealAmount - totalAllocated) + '.';
        $('#modal_budget_tracker').css({ 'background': '#fff7ed', 'border-color': '#fed7aa' });
        $('#tracker_remaining_budget').css('color', '#b54708');
        $('#tracker_warning_msg').html(message).show();
        $('.modal-task-budget-input').css('border-color', '#f59e0b');
        return false;
      }

      $('#modal_budget_tracker').css({ 'background': '#edf8f1', 'border-color': '#b7e4c7' });
      $('#tracker_remaining_budget').css('color', '#16803c');
      $('#tracker_warning_msg').hide();
      $('.modal-task-budget-input').css('border-color', '');
      return true;
    }

    function formatCurrencyInputPreserveCursor(elem) {
      var raw = elem.value || '';
      var cursorPos = elem.selectionStart || 0;
      var digitsBeforeCursor = raw.substring(0, cursorPos).replace(/[^0-9]/g, '').length;
      var val = raw.replace(/[^0-9]/g, '');

      if (val) {
        var formatted = parseInt(val, 10).toLocaleString('id-ID');
        elem.value = formatted;

        var newCursor = 0;
        var digitCount = 0;
        for (var i = 0; i < formatted.length; i++) {
          if (/[0-9]/.test(formatted[i])) {
            digitCount++;
          }
          newCursor = i + 1;
          if (digitCount >= digitsBeforeCursor) {
            break;
          }
        }
        if (digitsBeforeCursor === 0) newCursor = 0;
        elem.setSelectionRange(newCursor, newCursor);
      } else {
        elem.value = '';
      }
    }

    $(document).on('input', '.modal-task-budget-input', function() {
      formatCurrencyInputPreserveCursor(this);
      recalculateTaskBudgets();
    });

    $(document).on('input', '#modal_deal_amount', function() {
      formatCurrencyInputPreserveCursor(this);
      distributeDealAmountToTasks();
    });

    $(document).on('input', '#shipment_shipping_fee', function() {
      formatCurrencyInputPreserveCursor(this);
    });

    $('#modal_jumlah_vt').on('input change keyup', function() {
      renderModalTaskRows();
    });

    // ==========================================
    // Shipment & Product Items Helpers
    // ==========================================
    function formatRupiah(num) {
      return 'Rp ' + Number(num).toLocaleString('id-ID');
    }

    function addShipmentItemRow(productId, qty) {
      var $tbody = $('#tbody_modal_shipment_items');
      var rowIdx = $tbody.find('tr').length;
      productId = productId || '';
      qty = qty || 1;

      var productOptions = '<option value="">-- Pilih Produk Campaign --</option>';
      if (productsList && productsList.length > 0) {
        if (productsList.length === 1 && !productId) {
          productId = productsList[0].id;
        }
        $.each(productsList, function(idx, p) {
          var sel = (productId == p.id) ? 'selected' : '';
          var stockBadge = p.stock > 0 ? '(Stok: ' + p.stock + ')' : '(STOK HABIS)';
          productOptions += '<option value="' + p.id + '" data-price="' + p.price + '" data-stock="' + p.stock + '" ' + sel + '>';
          productOptions += '[' + p.sku + '] ' + p.name + ' ' + stockBadge;
          productOptions += '</option>';
        });
      } else {
        productOptions = '<option value="">-- Belum ada produk pada Campaign ini --</option>';
      }

      var tr = '<tr class="shipment-item-row" data-index="' + rowIdx + '">';
      tr += '  <td style="text-align: center; vertical-align: middle; font-weight: bold; color: #777;" class="row-num">' + (rowIdx + 1) + '</td>';
      tr += '  <td style="vertical-align: middle;">';
      tr += '    <select class="form-control input-sm shipment-product-select" name="shipment_items[' + rowIdx + '][product_id]" required style="border-radius: 3px;">' + productOptions + '</select>';
      tr += '  </td>';
      tr += '  <td style="vertical-align: middle;">';
      tr += '    <input type="number" class="form-control input-sm shipment-qty-input text-center" name="shipment_items[' + rowIdx + '][qty]" value="' + qty + '" min="1" required style="border-radius: 3px; font-weight: bold;" />';
      tr += '  </td>';
      tr += '  <td style="text-align: right; vertical-align: middle; font-size: 12px; font-weight: bold; color: #333;" class="row-subtotal">Rp 0</td>';
      tr += '  <td style="text-align: center; vertical-align: middle;">';
      tr += '    <button type="button" class="btn btn-xs btn-danger btn-remove-shipment-item" title="Hapus"><i class="fa fa-trash"></i></button>';
      tr += '  </td>';
      tr += '</tr>';

      $tbody.append(tr);
      recalculateShipmentTotals();
    }

    function recalculateShipmentTotals() {
      var totalQty = 0;
      var totalVal = 0;

      $('#tbody_modal_shipment_items tr.shipment-item-row').each(function(idx) {
        $(this).find('.row-num').text(idx + 1);
        var $select = $(this).find('.shipment-product-select');
        var $qtyInput = $(this).find('.shipment-qty-input');
        var qty = parseInt($qtyInput.val()) || 0;
        var $opt = $select.find(':selected');
        var price = parseFloat($opt.data('price')) || 0;
        var stock = parseInt($opt.data('stock')) || 0;

        var subtotal = qty * price;
        totalQty += qty;
        totalVal += subtotal;

        $(this).find('.row-subtotal').text(formatRupiah(subtotal));

        // Stock warn if requested qty > stock
        if (stock > 0 && qty > stock) {
          $qtyInput.css('border-color', '#dd4b39');
        } else {
          $qtyInput.css('border-color', '');
        }
      });

      $('#label_total_shipment_qty').text(totalQty + ' pcs');
      $('#label_total_shipment_val').text(formatRupiah(totalVal));
    }

    $('#btn_add_shipment_item').on('click', function() {
      addShipmentItemRow();
    });

    $(document).on('change', '.shipment-product-select', function() {
      recalculateShipmentTotals();
    });

    $(document).on('input change keyup', '.shipment-qty-input', function() {
      recalculateShipmentTotals();
    });

    $(document).on('click', '.btn-remove-shipment-item', function() {
      if ($('#tbody_modal_shipment_items tr').length <= 1) {
        toastr['warning']('Minimal harus ada 1 produk sample yang dikirimkan.');
        return;
      }
      $(this).closest('tr').remove();
      recalculateShipmentTotals();
    });

    function autoGenerateTrackingNo() {
      var courier = $('#shipment_courier').val();
      if (!courier) {
        toastr['warning']('Pilih kurir terlebih dahulu untuk generate no. resi.');
        return;
      }
      var $btn = $('#btn_generate_tracking_no');
      $btn.prop('disabled', true).html('<i class="fa fa-spinner fa-spin"></i>');

      $.ajax({
        url: '<?= site_url("administrator/campaign_kols/generate_tracking_no"); ?>',
        type: 'GET',
        data: { courier: courier },
        dataType: 'json',
        success: function(res) {
          $btn.prop('disabled', false).html('<i class="fa fa-magic"></i> Auto');
          if (res.success && res.tracking_no) {
            $('#shipment_tracking_no').val(res.tracking_no);
            toastr['success']('No. resi unik berhasil digenerate: ' + res.tracking_no);
          }
        },
        error: function() {
          $btn.prop('disabled', false).html('<i class="fa fa-magic"></i> Auto');
          toastr['error']('Gagal mengenerate no. resi.');
        }
      });
    }

    $(document).on('click', '#btn_generate_tracking_no', function(e) {
      e.preventDefault();
      autoGenerateTrackingNo();
    });

    $(document).on('change', '#shipment_courier', function() {
      if ($(this).val() && !$('#shipment_tracking_no').val()) {
        autoGenerateTrackingNo();
      }
    });

    // ==========================================
    // Status Change Trigger & Modal Launch
    // ==========================================
    $(document).on('change', '.quick-status-select', function() {
      var $select = $(this);
      currentActiveSelect = $select;
      var id = $select.data('id');
      var originalStatus = $select.data('original-status');
      var newStatus = $select.val();
      var currentJumlahVt = parseInt($select.data('jumlah-vt')) || 1;
      var campaignName = $select.data('campaign-name');
      var kolName = $select.data('kol-name');

      var taskAllowedStatuses = ['ASSIGNED', 'ACTIVE', 'COMPLETED'];

      if (taskAllowedStatuses.indexOf(newStatus) !== -1) {
        // Open Modal to configure tasks & shipment
        $('#modal_campaign_kol_id').val(id);
        $('#modal_new_status').val(newStatus);
        $('#modal_info_campaign').text(campaignName || '-');
        $('#modal_info_kol').text(kolName || '-');
        $('#modal_info_status_badge').text(newStatus).removeClass('label-primary label-success label-info label-warning label-danger');

        if (newStatus === 'ACTIVE') $('#modal_info_status_badge').addClass('label-success');
        else if (newStatus === 'ASSIGNED') $('#modal_info_status_badge').addClass('label-info');
        else $('#modal_info_status_badge').addClass('label-primary');

        $('#modal_jumlah_vt').val(currentJumlahVt > 0 ? currentJumlahVt : 1);
        $('#modal_task_loading').show();
        $('#modal_tasks_table_tbody').empty();
        $('#tbody_modal_shipment_items').empty();
        
        goToStep(1);
        $('#modal_task_configuration').modal('show');

        $.ajax({
          url: '<?= site_url("administrator/campaign_kols/get_tasks_json"); ?>/' + id,
          type: 'GET',
          dataType: 'json',
          success: function(res) {
            $('#modal_task_loading').hide();
            if (res.success) {
              modalExistingTasks = res.tasks || [];
              modalExistingShipment = res.shipment || null;
              modalExistingShipmentItems = res.shipment_items || [];
              modalKolData = res.kol || null;
              productsList = res.products || [];
              if (res.platforms) {
                platformsList = res.platforms;
              }
              if (res.variants) {
                variantsList = res.variants;
              }

              if (res.campaign_name) $('#modal_info_campaign').text(res.campaign_name);
              modalCampaignStartDate = res.campaign_start_date || null;
              modalCampaignEndDate = res.campaign_end_date || null;
              modalCampaignRemainingBudget = parseFloat(res.campaign_remaining_budget) || 0;
              
              if (res.kol_name) $('#modal_info_kol').text(res.kol_name);
              if (res.campaign_kol) {
                if (parseInt(res.campaign_kol.jumlah_vt) > 0) {
                  $('#modal_jumlah_vt').val(res.campaign_kol.jumlah_vt);
                }
                var dealAmt = parseFloat(res.campaign_kol.deal_amount) || 0;
                var cleanDealAmt = Math.round(dealAmt);
                $('#modal_deal_amount').val(cleanDealAmt > 0 ? cleanDealAmt.toLocaleString('id-ID') : '');
              }

              renderModalTaskRows();

              // Pre-fill Step 2 Shipment Form if existing (fallback to KOL profile incl. phone)
              var kolPhone = (modalKolData && modalKolData.phone) ? modalKolData.phone : '';
              var kolAddrParts = [];
              if (modalKolData) {
                if (modalKolData.address) kolAddrParts.push(modalKolData.address);
                if (modalKolData.city) kolAddrParts.push(modalKolData.city);
                if (modalKolData.province) kolAddrParts.push(modalKolData.province);
              }
              var kolAddr = kolAddrParts.join(', ');
              if (modalExistingShipment) {
                $('#shipment_recipient_name').val(modalExistingShipment.recipient_name || (modalKolData ? (modalKolData.name || '') : ''));
                $('#shipment_recipient_phone').val(modalExistingShipment.recipient_phone || kolPhone);
                $('#shipment_shipping_address').val(modalExistingShipment.shipping_address || kolAddr);
                $('#shipment_courier').val(modalExistingShipment.courier || '');
                $('#shipment_tracking_no').val(modalExistingShipment.tracking_no || '');
                var _fee = parseFloat(modalExistingShipment.shipping_fee) || 0;
                $('#shipment_shipping_fee').val(_fee > 0 ? _fee.toLocaleString('id-ID') : '0');
                $('#shipment_status').val(modalExistingShipment.status || 'PENDING');
                $('#shipment_notes').val(modalExistingShipment.notes || '');
              } else {
                $('#shipment_recipient_name').val(modalKolData ? (modalKolData.name || '') : '');
                $('#shipment_recipient_phone').val(kolPhone);
                $('#shipment_shipping_address').val(kolAddr);
                $('#shipment_courier').val('');
                $('#shipment_tracking_no').val('');
                $('#shipment_shipping_fee').val('0');
                $('#shipment_status').val('PENDING');
                $('#shipment_notes').val('');
              }
              if (!productsList || productsList.length === 0) {
                toastr['warning']('Campaign ini belum assign produk. Tambahkan produk pada campaign dulu agar bisa dipilih di pengiriman.');
              }

              // Pre-fill Shipment Items
              $('#tbody_modal_shipment_items').empty();
              if (modalExistingShipmentItems && modalExistingShipmentItems.length > 0) {
                $.each(modalExistingShipmentItems, function(idx, itm) {
                  addShipmentItemRow(itm.product_id, itm.qty);
                });
              }

            } else {
              toastr['error'](res.message || 'Gagal memuat data task.');
              renderModalTaskRows();
            }
          },
          error: function(xhr) {
            console.error('[Get Tasks Error]', xhr.status, xhr.statusText, xhr.responseText);
            $('#modal_task_loading').hide();
            renderModalTaskRows();
          }
        });

      } else {
        // Direct AJAX update for NEGOTIATION, REJECTED, CANCELLED
        if (newStatus === 'REJECTED') {
          swal({
            title: "Tolak Dealing KOL?",
            text: "Silakan masukkan alasan penolakan:",
            type: "input",
            showCancelButton: true,
            confirmButtonColor: "#dd4b39",
            confirmButtonText: "Tolak",
            cancelButtonText: "Batal",
            closeOnConfirm: false,
            closeOnCancel: true,
            inputPlaceholder: "Alasan penolakan..."
          }, function(inputValue) {
            if (inputValue === false) {
              $select.val(originalStatus);
              updateSelectStyle($select);
              return false;
            }
            if (inputValue === "") {
              swal.showInputError("Alasan penolakan wajib diisi!");
              return false;
            }
            
            var postData = {
              id: id,
              status: newStatus,
              jumlah_vt: 0,
              rejection_reason: inputValue
            };
            postData[csrfName] = csrfHash;
            executeDirectAjax(postData, $select, originalStatus, newStatus);
            swal.close();
          });
        } else {
          swal({
            title: "Ubah Status Assign?",
            text: "Anda akan mengubah status Dealing KOL menjadi " + newStatus,
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#3c8dbc",
            confirmButtonText: "Ya, Ubah!",
            cancelButtonText: "Batal",
            closeOnConfirm: true,
            closeOnCancel: true
          }, function(isConfirm) {
            if (isConfirm) {
              var postData = {
                id: id,
                status: newStatus,
                jumlah_vt: (newStatus === 'NEGOTIATION') ? currentJumlahVt : 0
              };
              postData[csrfName] = csrfHash;
              executeDirectAjax(postData, $select, originalStatus, newStatus);
            } else {
              $select.val(originalStatus);
              updateSelectStyle($select);
            }
          });
        }
      }
    });

    function executeDirectAjax(postData, $select, originalStatus, newStatus) {
      $.ajax({
        url: '<?= site_url("administrator/campaign_kols/update_status_tasks_ajax"); ?>',
        type: 'POST',
        dataType: 'json',
        data: postData,
        success: function(res) {
          if (res.csrf_hash) {
            csrfHash = res.csrf_hash;
            $('.csrf-token-field').val(csrfHash);
          }
          if (res.success) {
            toastr['success'](res.message);
            $select.data('original-status', newStatus);
            $select.data('jumlah-vt', res.jumlah_vt);
            updateSelectStyle($select);
            var $row = $select.closest('tr');
            $row.find('td:eq(5)').text(res.jumlah_vt);
            if (res.deal_date) { $row.find('td:eq(6)').text(res.deal_date); }
            if (res.rejection_reason !== undefined) { $row.find('td:eq(8)').text(res.rejection_reason || ''); }
            if (res.deal_amount !== undefined) { $row.find('td:eq(9)').text('Rp ' + (Math.round(parseFloat(res.deal_amount)) || 0).toLocaleString('id-ID')); }
            $row.find('td:eq(10)').text(res.task_count);
            
            var lockedStatuses = ['ASSIGNED', 'ACTIVE', 'COMPLETED'];
            if (lockedStatuses.indexOf(res.new_status) !== -1) {
              $select.prop('disabled', true);
              $select.css({
                'background-color': '#f4f6f9',
                'cursor': 'not-allowed',
                'opacity': '0.8'
              });
            }
          } else {
            toastr['error'](res.message);
            $select.val(originalStatus);
            updateSelectStyle($select);
          }
        },
        error: function(xhr) {
          console.error('[Update Status Error]', xhr.status, xhr.statusText, xhr.responseText);
          var errDetail = '';
          try {
            var parsed = JSON.parse(xhr.responseText);
            if (parsed.message) errDetail = ': ' + parsed.message;
          } catch(e) {}
          toastr['error']('Terjadi kesalahan saat menyimpan perubahan status (Error ' + xhr.status + ')' + errDetail);
          $select.val(originalStatus);
          updateSelectStyle($select);
        }
      });
    }

    // Close / Cancel modal
    $('.btn-close-modal-task').on('click', function() {
      $('#modal_task_configuration').modal('hide');
      if (currentActiveSelect) {
        var originalStatus = currentActiveSelect.data('original-status');
        currentActiveSelect.val(originalStatus);
        updateSelectStyle(currentActiveSelect);
      }
    });

    // Step 1: Next to Shipping button
    $('#btn_next_to_shipping').on('click', function() {
      // Validate Step 1 Task inputs
      var hasEmpty = false;
      $('#modal_step_1_container').find('input[required], select[required]').each(function() {
        if (!$(this).val()) {
          $(this).focus();
          toastr['warning']('Harap lengkapi semua field task bertanda bintang (*).');
          hasEmpty = true;
          return false;
        }
      });
      if (hasEmpty) return;

      // Validate total task budget vs deal amount
      var dealAmount = parseFloat($('#modal_deal_amount').val().toString().replace(/[^0-9]/g, '')) || 0;
      var totalTaskBudget = 0;
      $('#modal_tasks_table_tbody tr.modal-task-row').each(function() {
        totalTaskBudget += parseFloat($(this).find('.modal-task-budget-input').val().toString().replace(/[^0-9]/g, '')) || 0;
      });

      if (dealAmount <= 0 || totalTaskBudget !== dealAmount) {
        var budgetMessage = dealAmount <= 0
          ? 'Isi Deal Amount lebih dari Rp 0 sebelum lanjut.'
          : totalTaskBudget > dealAmount
            ? 'Total budget task (' + formatRupiah(totalTaskBudget) + ') melebihi nilai deal (' + formatRupiah(dealAmount) + ').'
            : 'Total budget task masih kurang ' + formatRupiah(dealAmount - totalTaskBudget) + '. Alokasi harus sama dengan nilai deal.';
        swal({
          title: 'Alokasi Budget Belum Sesuai',
          text: budgetMessage,
          type: 'warning',
          confirmButtonColor: '#1f4b6e'
        });
        return;
      }

      goToStep(2);
    });

    // Step 2: Back to Tasks button
    $('#btn_back_to_tasks').on('click', function() {
      goToStep(1);
    });

    // Step 2: Final Unified Submit
    $('#btn_save_all_assignment').on('click', function() {
      var form = $('#form_modal_task_config');
      var $btn = $(this);

      // Validate Step 2 inputs
      var recipientName = $('#shipment_recipient_name').val();
      var shippingAddress = $('#shipment_shipping_address').val();

      if (!recipientName) {
        $('#shipment_recipient_name').focus();
        toastr['warning']('Harap isi Nama Penerima pengiriman.');
        return;
      }

      if (!shippingAddress) {
        $('#shipment_shipping_address').focus();
        toastr['warning']('Harap isi Alamat Lengkap pengiriman.');
        return;
      }

      var hasEmptyProduct = false;
      var hasStockError = false;
      var totalItems = 0;

      $('#tbody_modal_shipment_items tr.shipment-item-row').each(function() {
        var pId = $(this).find('.shipment-product-select').val();
        var qty = parseInt($(this).find('.shipment-qty-input').val()) || 0;
        var stock = parseInt($(this).find('.shipment-product-select :selected').data('stock')) || 0;

        if (!pId || qty <= 0) {
          hasEmptyProduct = true;
          return false;
        }

        if (stock > 0 && qty > stock) {
          hasStockError = true;
          return false;
        }

        totalItems++;
      });

      if (hasEmptyProduct || totalItems === 0) {
        toastr['warning']('Harap pilih produk dan tentukan jumlah kirim minimal 1.');
        return;
      }

      if (hasStockError) {
        toastr['error']('Jumlah pengiriman melebihi stok produk yang tersedia di gudang.');
        return;
      }

      $btn.prop('disabled', true).html('<i class="fa fa-spinner fa-spin"></i> Menyimpan Assignment & Pengiriman...');

      var data_post = form.serializeArray();
      $.each(data_post, function(i, field) {
        if (field.name === 'deal_amount' || field.name === 'shipment[shipping_fee]' || /^tasks\[\d+\]\[budget\]$/.test(field.name)) {
          var cleanNum = parseInt(field.value.toString().split(',')[0].replace(/[^0-9]/g, ''), 10);
          field.value = !isNaN(cleanNum) ? cleanNum : 0;
        }
      });

      $.ajax({
        url: '<?= site_url("administrator/campaign_kols/update_status_tasks_ajax"); ?>',
        type: 'POST',
        dataType: 'json',
        data: $.param(data_post),
        success: function(res) {
          $btn.prop('disabled', false).html('<i class="fa fa-check"></i> Simpan Task & Pengiriman');
          if (res.csrf_hash) {
            csrfHash = res.csrf_hash;
            $('.csrf-token-field').val(csrfHash);
          }
          if (res.success) {
            toastr['success'](res.message);
            $('#modal_task_configuration').modal('hide');
            if (currentActiveSelect) {
              currentActiveSelect.data('original-status', res.new_status);
              currentActiveSelect.data('jumlah-vt', res.jumlah_vt);
              currentActiveSelect.val(res.new_status);
              updateSelectStyle(currentActiveSelect);
              // Update table row values in DOM
              var $row = currentActiveSelect.closest('tr');
              $row.find('td:eq(5)').text(res.jumlah_vt);
              if (res.deal_date) { $row.find('td:eq(6)').text(res.deal_date); }
              if (res.rejection_reason !== undefined) { $row.find('td:eq(8)').text(res.rejection_reason || ''); }
              if (res.deal_amount !== undefined) { $row.find('td:eq(9)').text('Rp ' + (Math.round(parseFloat(res.deal_amount)) || 0).toLocaleString('id-ID')); }
              $row.find('td:eq(10)').text(res.task_count);

              var lockedStatuses = ['ASSIGNED', 'ACTIVE', 'COMPLETED'];
              if (lockedStatuses.indexOf(res.new_status) !== -1) {
                currentActiveSelect.prop('disabled', true);
                currentActiveSelect.css({
                  'background-color': '#f4f6f9',
                  'cursor': 'not-allowed',
                  'opacity': '0.8'
                });
              }
            }
          } else {
            toastr['error'](res.message || 'Gagal menyimpan konfigurasi.');
          }
        },
        error: function(xhr) {
          console.error('[Save Modal Assignment Error]', xhr.status, xhr.statusText, xhr.responseText);
          $btn.prop('disabled', false).html('<i class="fa fa-check"></i> Simpan Task & Pengiriman');
          var errDetail = '';
          try {
            var parsed = JSON.parse(xhr.responseText);
            if (parsed.message) errDetail = ' - ' + parsed.message;
          } catch(e) {
            if (xhr.responseText) {
              errDetail = ' - ' + xhr.responseText.replace(/<[^>]*>?/gm, '').substring(0, 100);
            }
          }
          toastr['error']('Terjadi kesalahan pada server (Error ' + xhr.status + ')' + errDetail);
        }
      });
    });



  }); /*end doc ready*/
</script>